package copilotcli

import (
	"encoding/json"
	"errors"
	"fmt"
	"slices"
	"time"
)

// HookHost identifies which host format produced a copilot-compatible hook payload.
type HookHost string

const (
	HostUnknown    HookHost = "unknown"
	HostCopilotCLI HookHost = "copilot-cli"
	HostVSCode     HookHost = "vscode"
)

// VS Code hookEventName values (from official VS Code docs).
// See: https://code.visualstudio.com/docs/copilot/customization/hooks
const (
	VSCodeEventSessionStart     = "SessionStart"
	VSCodeEventUserPromptSubmit = "UserPromptSubmit"
	VSCodeEventStop             = "Stop"
	VSCodeEventPreToolUse       = "PreToolUse"
	VSCodeEventPostToolUse      = "PostToolUse"
	VSCodeEventPreCompact       = "PreCompact"
	VSCodeEventSubagentStart    = "SubagentStart"
	VSCodeEventSubagentStop     = "SubagentStop"
)

// vsCodeEventToHookNames maps each VS Code hookEventName to the CLI hook name(s)
// that are allowed to carry that event. "Stop" maps to both agent-stop and
// session-end because VS Code uses a single Stop event where Copilot CLI
// distinguishes the two.
var vsCodeEventToHookNames = map[string][]string{
	VSCodeEventUserPromptSubmit: {HookNameUserPromptSubmitted},
	VSCodeEventSessionStart:     {HookNameSessionStart},
	VSCodeEventStop:             {HookNameAgentStop, HookNameSessionEnd},
	VSCodeEventSubagentStop:     {HookNameSubagentStop},
	VSCodeEventPreToolUse:       {HookNamePreToolUse},
	VSCodeEventPostToolUse:      {HookNamePostToolUse},
	VSCodeEventPreCompact:       {},
	VSCodeEventSubagentStart:    {},
}

type hookEnvelope struct {
	Host           HookHost
	SessionID      string
	Prompt         string
	TranscriptPath string
	HookEventName  string
	Source         string
	InitialPrompt  string
	StopReason     string
	Reason         string
	Timestamp      time.Time
}

func parseHookEnvelope(data []byte) (*hookEnvelope, error) {
	if len(data) == 0 {
		return nil, errors.New("empty hook input")
	}

	var raw map[string]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		return nil, fmt.Errorf("failed to parse hook input: %w", err)
	}

	env := &hookEnvelope{
		Host:           detectHookHost(raw),
		SessionID:      firstString(raw, "sessionId", "session_id"),
		Prompt:         firstString(raw, "prompt"),
		TranscriptPath: firstString(raw, "transcriptPath", "transcript_path"),
		HookEventName:  firstString(raw, "hookEventName"),
		Source:         firstString(raw, "source"),
		InitialPrompt:  firstString(raw, "initialPrompt"),
		StopReason:     firstString(raw, "stopReason"),
		Reason:         firstString(raw, "reason"),
	}

	ts, err := parseTimestamp(raw["timestamp"])
	if err != nil {
		return nil, fmt.Errorf("failed to parse hook input: %w", err)
	}
	env.Timestamp = ts

	if env.Timestamp.IsZero() {
		env.Timestamp = time.Now()
	}

	return env, nil
}

func detectHookHost(raw map[string]json.RawMessage) HookHost {
	if isJSONString(raw["hookEventName"]) {
		return HostVSCode
	}
	if isJSONString(raw["transcript_path"]) {
		return HostVSCode
	}
	if isJSONString(raw["timestamp"]) {
		return HostVSCode
	}
	if _, ok := raw["transcriptPath"]; ok {
		return HostCopilotCLI
	}
	if isJSONNumber(raw["timestamp"]) {
		return HostCopilotCLI
	}
	return HostUnknown
}

func firstString(raw map[string]json.RawMessage, keys ...string) string {
	for _, key := range keys {
		value, ok := raw[key]
		if !ok {
			continue
		}
		var s string
		if err := json.Unmarshal(value, &s); err == nil {
			return s
		}
	}
	return ""
}

func parseTimestamp(raw json.RawMessage) (time.Time, error) {
	if len(raw) == 0 || string(raw) == "null" {
		return time.Time{}, nil
	}

	var millis int64
	if err := json.Unmarshal(raw, &millis); err == nil {
		if millis == 0 {
			return time.Time{}, nil // Treat epoch as missing — triggers time.Now() fallback.
		}
		return time.UnixMilli(millis), nil
	}

	var ts string
	if err := json.Unmarshal(raw, &ts); err != nil {
		return time.Time{}, fmt.Errorf("unmarshal timestamp string: %w", err)
	}

	parsed, err := time.Parse(time.RFC3339Nano, ts)
	if err != nil {
		return time.Time{}, fmt.Errorf("parse timestamp %q: %w", ts, err)
	}
	return parsed, nil
}

func isJSONString(raw json.RawMessage) bool {
	if len(raw) == 0 || raw[0] != '"' {
		return false
	}
	var s string
	return json.Unmarshal(raw, &s) == nil
}

func isJSONNumber(raw json.RawMessage) bool {
	if len(raw) == 0 || raw[0] == 'n' {
		return false
	}
	var n int64
	return json.Unmarshal(raw, &n) == nil
}

// validateVSCodeEvent checks whether the hookEventName is consistent with the
// CLI hook subcommand that was invoked. Returns true if the event should be
// processed, false if it should be silently skipped (mismatch or unknown event).
func validateVSCodeEvent(env *hookEnvelope, hookName string) bool {
	hookEventName := env.HookEventName
	allowedHooks, known := vsCodeEventToHookNames[hookEventName]
	if !known {
		return false
	}
	if !slices.Contains(allowedHooks, hookName) {
		return false
	}

	// VS Code overloads "Stop" for both end-of-turn and terminal session-stop
	// payloads. Route them by reason to avoid ending sessions on ordinary turns.
	if hookEventName == VSCodeEventStop {
		isTerminal := isTerminalVSCodeStop(env)
		switch hookName {
		case HookNameAgentStop:
			return !isTerminal
		case HookNameSessionEnd:
			return isTerminal
		}
	}

	return true
}

func isTerminalVSCodeStop(env *hookEnvelope) bool {
	if env.Reason != "" {
		return true
	}

	switch env.StopReason {
	case "", "end_turn":
		return false
	default:
		return true
	}
}


--- cmd/entire/cli/agent/copilotcli/copilotcli.go
// Package copilotcli implements the Agent interface for GitHub Copilot CLI.
package copilotcli

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
)

//nolint:gochecknoinits // Agent self-registration is the intended pattern
func init() {
	agent.Register(agent.AgentNameCopilotCLI, NewCopilotCLIAgent)
}

// CopilotCLIAgent implements the Agent interface for GitHub Copilot CLI.
//
//nolint:revive // CopilotCLIAgent is clearer than Agent in this context
type CopilotCLIAgent struct {
	CommandRunner agent.TextCommandRunner
}

// NewCopilotCLIAgent creates a new Copilot CLI agent instance.
func NewCopilotCLIAgent() agent.Agent {
	return &CopilotCLIAgent{}
}

// Name returns the agent registry key.
func (c *CopilotCLIAgent) Name() types.AgentName {
	return agent.AgentNameCopilotCLI
}

// Type returns the agent type identifier.
func (c *CopilotCLIAgent) Type() types.AgentType {
	return agent.AgentTypeCopilotCLI
}

// Description returns a human-readable description.
func (c *CopilotCLIAgent) Description() string {
	return "Copilot CLI - GitHub's AI-powered coding agent"
}

// IsPreview returns true because this is a new integration.
func (c *CopilotCLIAgent) IsPreview() bool { return true }

// DetectPresence checks if Entire hooks are installed in the Copilot CLI config.
// Delegates to AreHooksInstalled which checks .github/hooks/entire.json for Entire hook entries.
func (c *CopilotCLIAgent) DetectPresence(ctx context.Context) (bool, error) {
	return c.AreHooksInstalled(ctx), nil
}

// GetSessionID extracts the session ID from hook input.
func (c *CopilotCLIAgent) GetSessionID(input *agent.HookInput) string {
	return input.SessionID
}

// GetSessionDir returns the directory where Copilot CLI stores session transcripts.
func (c *CopilotCLIAgent) GetSessionDir(_ string) (string, error) {
	if override := os.Getenv("ENTIRE_TEST_COPILOT_SESSION_DIR"); override != "" {
		return override, nil
	}

	homeDir, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("failed to get home directory: %w", err)
	}

	return filepath.Join(homeDir, ".copilot", "session-state"), nil
}

// ResolveSessionFile returns the path to a Copilot CLI session transcript file.
// Copilot CLI stores transcripts at <sessionDir>/<sessionId>/events.jsonl.
func (c *CopilotCLIAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
	return filepath.Join(sessionDir, agentSessionID, "events.jsonl")
}

// ProtectedDirs returns directories that Copilot CLI uses for config/state.
func (c *CopilotCLIAgent) ProtectedDirs() []string {
	return []string{filepath.Join(".github", "hooks")}
}

// ReadSession reads a session from Copilot CLI's storage (JSONL transcript file).
func (c *CopilotCLIAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
	if input.SessionRef == "" {
		return nil, errors.New("session reference (transcript path) is required")
	}

	data, err := os.ReadFile(input.SessionRef)
	if err != nil {
		return nil, fmt.Errorf("failed to read transcript: %w", err)
	}

	// Parse events for ModifiedFiles; non-fatal if parsing fails since NativeData
	// is the authoritative session content. ReadSession has no context.Context so
	// we cannot log here — scanner errors are surfaced by other code paths that
	// do have context (e.g. ExtractModifiedFilesFromOffset, ExtractPrompts).
	events, _ := parseEventsFromBytes(data) //nolint:errcheck // best-effort extraction
	var modifiedFiles []string
	if len(events) > 0 {
		modifiedFiles = extractModifiedFilesFromEvents(events)
	}

	return &agent.AgentSession{
		SessionID:     input.SessionID,
		AgentName:     c.Name(),
		SessionRef:    input.SessionRef,
		StartTime:     time.Now(),
		NativeData:    data,
		ModifiedFiles: modifiedFiles,
	}, nil
}

// WriteSession writes a session to Copilot CLI's storage (JSONL transcript file).
func (c *CopilotCLIAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
	if session == nil {
		return errors.New("session is nil")
	}

	if session.AgentName != "" && session.AgentName != c.Name() {
		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
	}

	if session.SessionRef == "" {
		return errors.New("session reference (transcript path) is required")
	}

	if len(session.NativeData) == 0 {
		return errors.New("session has no native data to write")
	}

	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
		return fmt.Errorf("failed to write transcript: %w", err)
	}

	return nil
}

// FormatResumeCommand returns a command to resume a Copilot CLI session.
func (c *CopilotCLIAgent) FormatResumeCommand(sessionID string) string {
	return "copilot --resume " + sessionID
}

// ReadTranscript reads the raw JSONL transcript bytes for a session.
func (c *CopilotCLIAgent) ReadTranscript(sessionRef string) ([]byte, error) {
	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
	if err != nil {
		return nil, fmt.Errorf("failed to read transcript: %w", err)
	}
	return data, nil
}

// ChunkTranscript splits a JSONL transcript at line boundaries.
func (c *CopilotCLIAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
	chunks, err := agent.ChunkJSONL(content, maxSize)
	if err != nil {
		return nil, fmt.Errorf("failed to chunk JSONL transcript: %w", err)
	}
	return chunks, nil
}

// ReassembleTranscript concatenates JSONL chunks with newlines.
func (c *CopilotCLIAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
	return agent.ReassembleJSONL(chunks), nil
}


--- cmd/entire/cli/agent/copilotcli/generate.go
package copilotcli

import (
	"context"
	"fmt"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// GenerateText sends a prompt to the Copilot CLI and returns the raw text response.
//
// The prompt is piped via stdin rather than -p to avoid argv size limits.
// --allow-all-tools is required for non-interactive mode; --disable-builtin-mcps
// skips loading the GitHub MCP server that isn't needed for summary text
// generation and reduces per-call input tokens.
func (c *CopilotCLIAgent) GenerateText(ctx context.Context, prompt string, model string) (string, error) {
	args := []string{"--allow-all-tools", "--disable-builtin-mcps"}
	if model != "" {
		args = append(args, "--model", model)
	}

	result, err := agent.RunIsolatedTextGeneratorCLI(ctx, c.CommandRunner, "copilot", "copilot", args, prompt)
	if err != nil {
		return "", fmt.Errorf("copilot text generation failed: %w", err)
	}
	return result, nil
}


--- cmd/entire/cli/agent/copilotcli/hooks.go
package copilotcli

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// HooksFileName is the hooks file managed by Entire for Copilot CLI.
const HooksFileName = "entire.json"

// hooksDir is the directory within the repo where Copilot CLI looks for hook configs.
const hooksDir = ".github/hooks"

// entireHookPrefixes are command prefixes that identify Entire hooks in the bash field.
var entireHookPrefixes = []string{
	"entire ",
	`go run "$(git rev-parse --show-toplevel)"/cmd/entire/main.go `,
}

// hookConfigKey maps our kebab-case hook names to camelCase JSON keys.
var hookConfigKey = map[string]string{
	HookNameUserPromptSubmitted: "userPromptSubmitted",
	HookNameSessionStart:        "sessionStart",
	HookNameAgentStop:           "agentStop",
	HookNameSessionEnd:          "sessionEnd",
	HookNameSubagentStop:        "subagentStop",
	HookNamePreToolUse:          "preToolUse",
	HookNamePostToolUse:         "postToolUse",
	HookNameErrorOccurred:       "errorOccurred",
}

// InstallHooks installs Copilot CLI hooks in .github/hooks/entire.json.
// If force is true, removes existing Entire hooks before installing.
// Returns the number of hooks installed.
// Unknown top-level fields and hook types are preserved on round-trip.
func (c *CopilotCLIAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
	worktreeRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		worktreeRoot = "."
	}

	hooksPath := filepath.Join(worktreeRoot, hooksDir, HooksFileName)

	// Use raw maps to preserve unknown fields on round-trip
	var rawFile map[string]json.RawMessage
	var rawHooks map[string]json.RawMessage

	existingData, readErr := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
	switch {
	case readErr == nil:
		if err := json.Unmarshal(existingData, &rawFile); err != nil {
			return 0, fmt.Errorf("failed to parse existing %s: %w", HooksFileName, err)
		}
		if hooksRaw, ok := rawFile["hooks"]; ok {
			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
				return 0, fmt.Errorf("failed to parse hooks in %s: %w", HooksFileName, err)
			}
		}
		if _, ok := rawFile["version"]; !ok {
			rawFile["version"] = json.RawMessage(`1`)
		}
	case errors.Is(readErr, os.ErrNotExist):
		rawFile = map[string]json.RawMessage{
			"version": json.RawMessage(`1`),
		}
	default:
		return 0, fmt.Errorf("failed to read %s: %w", HooksFileName, readErr)
	}

	if rawHooks == nil {
		rawHooks = make(map[string]json.RawMessage)
	}

	// Parse existing entries for each hook type we manage
	hookEntries := make(map[string][]CopilotHookEntry)
	for _, hookName := range c.HookNames() {
		key := hookConfigKey[hookName]
		var entries []CopilotHookEntry
		if err := parseCopilotHookType(rawHooks, key, &entries); err != nil {
			return 0, fmt.Errorf("failed to parse %s hooks: %w", key, err)
		}
		hookEntries[hookName] = entries
	}

	// If force, remove existing Entire hooks first
	if force {
		for hookName, entries := range hookEntries {
			hookEntries[hookName] = removeEntireHooks(entries)
		}
	}

	// Define command prefix
	var cmdPrefix string
	if localDev {
		cmdPrefix = `go run "$(git rev-parse --show-toplevel)"/cmd/entire/main.go hooks copilot-cli `
	} else {
		cmdPrefix = "entire hooks copilot-cli "
	}

	count := 0

	// Add hooks that don't already exist
	for _, hookName := range c.HookNames() {
		cmd := cmdPrefix + hookName
		if !localDev {
			cmd = agent.WrapProductionSilentHookCommand(cmd)
		}
		entries := hookEntries[hookName]
		if !hookBashExists(entries, cmd) {
			entries = append(entries, CopilotHookEntry{
				Type:    "command",
				Bash:    cmd,
				Comment: "Entire CLI",
			})
			hookEntries[hookName] = entries
			count++
		}
	}

	if count == 0 {
		return 0, nil
	}

	// Marshal modified hook types back into rawHooks
	for _, hookName := range c.HookNames() {
		key := hookConfigKey[hookName]
		if err := marshalCopilotHookType(rawHooks, key, hookEntries[hookName]); err != nil {
			return 0, fmt.Errorf("failed to marshal %s hooks: %w", key, err)
		}
	}

	// Marshal hooks and update raw file
	hooksJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawHooks)
	if err != nil {
		return 0, fmt.Errorf("failed to marshal hooks: %w", err)
	}
	rawFile["hooks"] = hooksJSON

	// Write to file
	if err := os.MkdirAll(filepath.Dir(hooksPath), 0o750); err != nil {
		return 0, fmt.Errorf("failed to create %s directory: %w", hooksDir, err)
	}

	output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
	if err != nil {
		return 0, fmt.Errorf("failed to marshal %s: %w", HooksFileName, err)
	}

	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
		return 0, fmt.Errorf("failed to write %s: %w", HooksFileName, err)
	}

	return count, nil
}

// UninstallHooks removes Entire hooks from Copilot CLI's entire.json.
// Unknown top-level fields and hook types are preserved on round-trip.
func (c *CopilotCLIAgent) UninstallHooks(ctx context.Context) error {
	worktreeRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		worktreeRoot = "."
	}
	hooksPath := filepath.Join(worktreeRoot, hooksDir, HooksFileName)
	data, err := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil // No hooks file means nothing to uninstall
		}
		return fmt.Errorf("failed to read %s: %w", HooksFileName, err)
	}

	var rawFile map[string]json.RawMessage
	if err := json.Unmarshal(data, &rawFile); err != nil {
		return fmt.Errorf("failed to parse %s: %w", HooksFileName, err)
	}

	var rawHooks map[string]json.RawMessage
	if hooksRaw, ok := rawFile["hooks"]; ok {
		if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
			return fmt.Errorf("failed to parse hooks in %s: %w", HooksFileName, err)
		}
	}
	if rawHooks == nil {
		rawHooks = make(map[string]json.RawMessage)
	}

	// Parse and remove Entire hooks from each hook type we manage
	for _, hookName := range c.HookNames() {
		key := hookConfigKey[hookName]
		var entries []CopilotHookEntry
		if err := parseCopilotHookType(rawHooks, key, &entries); err != nil {
			return fmt.Errorf("failed to parse %s hooks: %w", key, err)
		}
		entries = removeEntireHooks(entries)
		if err := marshalCopilotHookType(rawHooks, key, entries); err != nil {
			return fmt.Errorf("failed to marshal %s hooks: %w", key, err)
		}
	}

	// Marshal hooks back (preserving unknown hook types)
	if len(rawHooks) > 0 {
		hooksJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawHooks)
		if err != nil {
			return fmt.Errorf("failed to marshal hooks: %w", err)
		}
		rawFile["hooks"] = hooksJSON
	} else {
		delete(rawFile, "hooks")
	}

	// Write back
	output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal %s: %w", HooksFileName, err)
	}

	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
		return fmt.Errorf("failed to write %s: %w", HooksFileName, err)
	}
	return nil
}

// AreHooksInstalled checks if Entire hooks are installed in the Copilot CLI config.
func (c *CopilotCLIAgent) AreHooksInstalled(ctx context.Context) bool {
	worktreeRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		worktreeRoot = "."
	}
	hooksPath := filepath.Join(worktreeRoot, hooksDir, HooksFileName)
	data, err := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
	if err != nil {
		if !errors.Is(err, os.ErrNotExist) {
			logging.Warn(ctx, "copilot-cli: failed to read hooks file", "path", hooksPath, "err", err)
		}
		return false
	}

	var hooksFile CopilotHooksFile
	if err := json.Unmarshal(data, &hooksFile); err != nil {
		logging.Warn(ctx, "copilot-cli: failed to parse hooks file", "path", hooksPath, "err", err)
		return false
	}

	return hasEntireHook(hooksFile.Hooks.UserPromptSubmitted) ||
		hasEntireHook(hooksFile.Hooks.SessionStart) ||
		hasEntireHook(hooksFile.Hooks.AgentStop) ||
		hasEntireHook(hooksFile.Hooks.SessionEnd) ||
		hasEntireHook(hooksFile.Hooks.SubagentStop) ||
		hasEntireHook(hooksFile.Hooks.PreToolUse) ||
		hasEntireHook(hooksFile.Hooks.PostToolUse) ||
		hasEntireHook(hooksFile.Hooks.ErrorOccurred)
}

// GetSupportedHooks returns the normalized lifecycle events this agent supports.
// Note: HookNames() returns 8 hooks but GetSupportedHooks() returns only 6.
// The two not listed here are:
//   - subagentStop: handled by ParseHookEvent (returns SubagentEnd), but there is no
//     HookType constant for subagent events (they use EventType instead).
//   - errorOccurred: pass-through hook with no lifecycle action (ParseHookEvent returns nil).
func (c *CopilotCLIAgent) GetSupportedHooks() []agent.HookType {
	return []agent.HookType{
		agent.HookSessionStart,
		agent.HookSessionEnd,
		agent.HookUserPromptSubmit,
		agent.HookStop,
		agent.HookPreToolUse,
		agent.HookPostToolUse,
	}
}

// parseCopilotHookType parses a specific hook type from rawHooks into the target slice.
func parseCopilotHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]CopilotHookEntry) error {
	if data, ok := rawHooks[hookType]; ok {
		if err := json.Unmarshal(data, target); err != nil {
			return fmt.Errorf("invalid JSON for hook type %s: %w", hookType, err)
		}
	}
	return nil
}

// marshalCopilotHookType marshals a hook type back into rawHooks.
// If the slice is empty, removes the key from rawHooks.
func marshalCopilotHookType(rawHooks map[string]json.RawMessage, hookType string, entries []CopilotHookEntry) error {
	if len(entries) == 0 {
		delete(rawHooks, hookType)
		return nil
	}
	data, err := jsonutil.MarshalWithNoHTMLEscape(entries)
	if err != nil {
		return fmt.Errorf("failed to marshal hook type %s: %w", hookType, err)
	}
	rawHooks[hookType] = data
	return nil
}

// hookBashExists checks if a hook with the given bash command already exists.
func hookBashExists(entries []CopilotHookEntry, bash string) bool {
	for _, entry := range entries {
		if entry.Bash == bash {
			return true
		}
	}
	return false
}

// isEntireHook checks if a hook entry's bash command belongs to Entire.
func isEntireHook(bash string) bool {
	return agent.IsManagedHookCommand(bash, entireHookPrefixes)
}

// hasEntireHook checks if any entry in the slice is an Entire hook.
func hasEntireHook(entries []CopilotHookEntry) bool {
	for _, entry := range entries {
		if isEntireHook(entry.Bash) {
			return true
		}
	}
	return false
}

// removeEntireHooks removes all Entire hooks from the slice.
func removeEntireHooks(entries []CopilotHookEntry) []CopilotHookEntry {
	result := make([]CopilotHookEntry, 0, len(entries))
	for _, entry := range entries {
		if !isEntireHook(entry.Bash) {
			result = append(result, entry)
		}
	}
	return result
}


