--- cmd/entire/cli/agent/chunking.go
package agent

import (
	"context"
	"encoding/json"
	"fmt"
	"sort"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent/types"
)

const (
	// MaxChunkSize is the maximum size for a single transcript chunk.
	// GitHub has a 100MB limit per blob, so we use 50MB to be safe.
	MaxChunkSize = 50 * 1024 * 1024 // 50MB

	// ChunkSuffix is the format for chunk file suffixes (e.g., ".001", ".002")
	ChunkSuffix = ".%03d"
)

// ChunkTranscript splits a transcript into chunks using the appropriate agent.
// If agentType is empty or the agent is not found, falls back to JSONL (line-based) chunking.
func ChunkTranscript(ctx context.Context, content []byte, agentType types.AgentType) ([][]byte, error) {
	if len(content) <= MaxChunkSize {
		return [][]byte{content}, nil
	}

	// Try to get the agent by type and use its format-aware chunking
	if agentType != "" {
		ag, err := GetByAgentType(agentType)
		if err == nil {
			chunks, chunkErr := ag.ChunkTranscript(ctx, content, MaxChunkSize)
			if chunkErr != nil {
				return nil, fmt.Errorf("agent chunking failed: %w", chunkErr)
			}
			return chunks, nil
		}
	}

	// Fall back to JSONL chunking (default)
	return ChunkJSONL(content, MaxChunkSize)
}

// ReassembleTranscript combines chunks back into a single transcript.
// If agentType is empty or the agent is not found, falls back to JSONL (line-based) reassembly.
func ReassembleTranscript(chunks [][]byte, agentType types.AgentType) ([]byte, error) {
	if len(chunks) == 0 {
		return nil, nil
	}
	if len(chunks) == 1 {
		return chunks[0], nil
	}

	// Try to get the agent by type and use its format-aware reassembly
	if agentType != "" {
		ag, err := GetByAgentType(agentType)
		if err == nil {
			result, reassembleErr := ag.ReassembleTranscript(chunks)
			if reassembleErr != nil {
				return nil, fmt.Errorf("agent reassembly failed: %w", reassembleErr)
			}
			return result, nil
		}
	}

	// Fall back to JSONL reassembly (default)
	return ReassembleJSONL(chunks), nil
}

// ChunkJSONL splits JSONL content at line boundaries.
// This is the default chunking for agents using JSONL format (like Claude Code).
func ChunkJSONL(content []byte, maxSize int) ([][]byte, error) {
	// Handle empty content
	if len(content) == 0 {
		return [][]byte{}, nil
	}

	lines := strings.Split(string(content), "\n")
	var chunks [][]byte
	var currentChunk strings.Builder

	for i, line := range lines {
		// Check if adding this line would exceed the chunk size
		lineWithNewline := line + "\n"

		// Check if a single line exceeds maxSize - this is an error since we can't split JSONL lines
		if len(lineWithNewline) > maxSize {
			return nil, fmt.Errorf("JSONL line %d exceeds maximum chunk size (%d bytes > %d bytes); cannot split a single JSON object", i+1, len(lineWithNewline), maxSize)
		}

		if currentChunk.Len()+len(lineWithNewline) > maxSize && currentChunk.Len() > 0 {
			// Save current chunk and start a new one
			chunks = append(chunks, []byte(strings.TrimSuffix(currentChunk.String(), "\n")))
			currentChunk.Reset()
		}
		currentChunk.WriteString(lineWithNewline)
	}

	// Add the last chunk if it has content
	if currentChunk.Len() > 0 {
		chunks = append(chunks, []byte(strings.TrimSuffix(currentChunk.String(), "\n")))
	}

	return chunks, nil
}

// ReassembleJSONL concatenates JSONL chunks with newlines.
func ReassembleJSONL(chunks [][]byte) []byte {
	var result strings.Builder
	for i, chunk := range chunks {
		result.Write(chunk)
		if i < len(chunks)-1 {
			result.WriteString("\n")
		}
	}
	return []byte(result.String())
}

// ChunkFileName returns the filename for a chunk at the given index.
// Index 0 returns the base filename, index 1+ returns with chunk suffix.
func ChunkFileName(baseName string, index int) string {
	if index == 0 {
		return baseName
	}
	return baseName + fmt.Sprintf(ChunkSuffix, index)
}

// ParseChunkIndex extracts the chunk index from a filename.
// Returns 0 for the base file (no suffix), or the chunk number for suffixed files.
// Returns -1 if the filename doesn't match the expected pattern.
func ParseChunkIndex(filename, baseName string) int {
	if filename == baseName {
		return 0
	}

	if !strings.HasPrefix(filename, baseName+".") {
		return -1
	}

	suffix := strings.TrimPrefix(filename, baseName+".")
	var index int
	if _, err := fmt.Sscanf(suffix, "%03d", &index); err != nil {
		return -1
	}
	return index
}

// SortChunkFiles sorts chunk filenames in order (base file first, then numbered chunks).
func SortChunkFiles(files []string, baseName string) []string {
	sorted := make([]string, len(files))
	copy(sorted, files)

	sort.Slice(sorted, func(i, j int) bool {
		idxI := ParseChunkIndex(sorted[i], baseName)
		idxJ := ParseChunkIndex(sorted[j], baseName)
		return idxI < idxJ
	})

	return sorted
}

// geminiTranscriptDetect is used for detecting Gemini JSON format.
type geminiTranscriptDetect struct {
	Messages []interface{} `json:"messages"`
}

// DetectAgentTypeFromContent detects the agent type from transcript content.
// Returns AgentTypeGemini if it appears to be Gemini JSON format, empty AgentType otherwise.
// This is used when the agent type is unknown but we need to chunk/reassemble correctly.
func DetectAgentTypeFromContent(content []byte) types.AgentType {
	// Quick check: Gemini JSON starts with { and has a messages array
	trimmed := strings.TrimSpace(string(content))
	if !strings.HasPrefix(trimmed, "{") {
		return ""
	}

	// Try to parse as Gemini JSON format (object with messages array)
	var transcript geminiTranscriptDetect
	if err := json.Unmarshal(content, &transcript); err != nil {
		return ""
	}

	// Must have at least one message to be considered Gemini format
	if len(transcript.Messages) > 0 {
		return AgentTypeGemini
	}

	return ""
}


--- cmd/entire/cli/agent/event.go
package agent

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"time"
)

// EventType represents a normalized lifecycle event from any agent.
// Agents translate their native hooks into these event types via ParseHookEvent.
type EventType int

const (
	// SessionStart indicates the agent session has begun.
	SessionStart EventType = iota + 1

	// TurnStart indicates the user submitted a prompt and the agent is about to work.
	TurnStart

	// TurnEnd indicates the agent finished responding to a prompt.
	TurnEnd

	// Compaction indicates the agent is about to compress its context window.
	// This triggers the same save logic as TurnEnd but also resets the transcript offset.
	Compaction

	// SessionEnd indicates the session has been terminated.
	SessionEnd

	// SubagentStart indicates a subagent (task) has been spawned.
	SubagentStart

	// SubagentEnd indicates a subagent (task) has completed.
	SubagentEnd

	// ModelUpdate indicates the agent reported the LLM model being used.
	// This fires on hooks that carry model info but have no other lifecycle action
	// (e.g., Gemini CLI's BeforeModel). The framework stores the model as a hint
	// for subsequent TurnStart/TurnEnd events in the same session.
	ModelUpdate

	// ToolUse indicates the agent ran a tool that touched files mid-turn.
	// Carries ModifiedFiles/NewFiles/DeletedFiles so the framework can populate
	// state.FilesTouched incrementally — without this, agents like Codex that
	// commit mid-turn (before TurnEnd fires) have no per-tool file accounting,
	// and the carry-forward path falls back to whole-transcript extraction.
	ToolUse
)

// String returns a human-readable name for the event type.
func (e EventType) String() string {
	switch e {
	case SessionStart:
		return "SessionStart"
	case TurnStart:
		return "TurnStart"
	case TurnEnd:
		return "TurnEnd"
	case Compaction:
		return "Compaction"
	case SessionEnd:
		return "SessionEnd"
	case SubagentStart:
		return "SubagentStart"
	case SubagentEnd:
		return "SubagentEnd"
	case ModelUpdate:
		return "ModelUpdate"
	case ToolUse:
		return "ToolUse"
	default:
		return "Unknown"
	}
}

// Event is a normalized lifecycle event produced by an agent's ParseHookEvent method.
// The framework dispatcher uses these events to drive checkpoint/session lifecycle actions.
type Event struct {
	// Type is the kind of lifecycle event.
	Type EventType

	// SessionID identifies the agent session.
	SessionID string

	// PreviousSessionID is non-empty when this event represents a session continuation
	// or handoff (e.g., Claude starting a new session ID after exiting plan mode).
	PreviousSessionID string

	// SessionRef is an agent-specific reference to the transcript (typically a file path).
	SessionRef string

	// Prompt is the user's prompt text (populated on TurnStart events).
	Prompt string

	// Model is the LLM model identifier (e.g., "claude-sonnet-4-20250514").
	// Populated on SessionStart (Claude Code), ModelUpdate (Gemini CLI BeforeModel),
	// and TurnStart/TurnEnd events when the agent provides model info.
	Model string

	// Timestamp is when the event occurred.
	Timestamp time.Time

	// ToolUseID identifies the tool invocation (for SubagentStart/SubagentEnd events).
	ToolUseID string

	// SubagentID identifies the subagent instance (for SubagentEnd events).
	SubagentID string

	// ToolInput is the raw tool input JSON (for subagent type/description extraction).
	// Used when both SubagentType and TaskDescription are empty (agents that don't provide
	// these fields directly parse them from ToolInput).
	ToolInput json.RawMessage

	// SubagentType is the kind of subagent (for SubagentStart/SubagentEnd events).
	// Used with TaskDescription instead of ToolInput
	SubagentType    string
	TaskDescription string

	// ModifiedFiles is the list of file paths modified by a subagent (SubagentEnd)
	// or a tool call (ToolUse). Paths may be absolute, cwd-relative, or
	// repo-relative; lifecycle handlers normalize against the worktree root.
	ModifiedFiles []string

	// NewFiles and DeletedFiles carry create/delete paths for ToolUse events,
	// kept separate from ModifiedFiles so consumers can reason about agent intent.
	NewFiles     []string
	DeletedFiles []string

	// CWD is the working directory the agent was running in when the event fired.
	// Set on ToolUse so cwd-relative payload paths can be resolved before
	// repo-root normalization.
	CWD string

	// ResponseMessage is an optional message to display to the user via the agent.
	ResponseMessage string

	// Hook-provided session metrics (populated by agents that report these via hooks).
	DurationMs        int64 // Session duration from agent hook (e.g., Cursor SessionEnd)
	TurnCount         int   // Number of agent turns/loops (e.g., Cursor Stop hook)
	ContextTokens     int   // Context window tokens used (e.g., Cursor PreCompact hook)
	ContextWindowSize int   // Total context window size (e.g., Cursor PreCompact hook)

	// Metadata holds agent-specific state that the framework stores and makes available
	// on subsequent events. Examples: Pi's activeLeafId, Cursor's is_background_agent.
	Metadata map[string]string
}

// ReadAndParseHookInput reads all bytes from stdin and unmarshals JSON into the given type.
// This is a shared helper for agent ParseHookEvent implementations.
func ReadAndParseHookInput[T any](stdin io.Reader) (*T, error) {
	data, err := io.ReadAll(stdin)
	if err != nil {
		return nil, fmt.Errorf("failed to read hook input: %w", err)
	}
	if len(data) == 0 {
		return nil, errors.New("empty hook input")
	}
	var result T
	if err := json.Unmarshal(data, &result); err != nil {
		return nil, fmt.Errorf("failed to parse hook input: %w", err)
	}
	return &result, nil
}


--- cmd/entire/cli/agent/hook_command.go
package agent

import (
	"fmt"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
)

type WarningFormat int

const (
	WarningFormatSingleLine WarningFormat = iota + 1
	WarningFormatMultiLine
)

func MissingEntireWarning(format WarningFormat) string {
	switch format {
	case WarningFormatSingleLine:
		return "Entire CLI is enabled but not installed or not on PATH. Installation guide: https://docs.entire.io/cli/installation#installation-methods"
	case WarningFormatMultiLine:
		return "\n\nEntire CLI is enabled but not installed or not on PATH.\nInstallation guide: https://docs.entire.io/cli/installation#installation-methods"
	default:
		return MissingEntireWarning(WarningFormatSingleLine)
	}
}

// WrapProductionSilentHookCommand exits successfully without output when the
// Entire CLI is missing from PATH.
func WrapProductionSilentHookCommand(command string) string {
	return fmt.Sprintf(
		`sh -c 'if ! command -v entire >/dev/null 2>&1; then exit 0; fi; exec %s'`,
		command,
	)
}

// WrapProductionJSONWarningHookCommand emits a JSON hook response with a
// systemMessage field on stdout when the Entire CLI is missing from PATH.
func WrapProductionJSONWarningHookCommand(command string, format WarningFormat) string {
	payload, err := jsonutil.MarshalWithNoHTMLEscape(struct {
		SystemMessage string `json:"systemMessage,omitempty"`
	}{
		SystemMessage: MissingEntireWarning(format),
	})
	if err != nil {
		// Fallback to plain text on stdout if JSON payload construction somehow fails.
		return WrapProductionPlainTextWarningHookCommand(command, format)
	}

	return fmt.Sprintf(
		`sh -c 'if ! command -v entire >/dev/null 2>&1; then printf "%%s\n" %q; exit 0; fi; exec %s'`,
		string(payload),
		command,
	)
}

// WrapProductionPlainTextWarningHookCommand emits the warning as plain
// text to stdout when the Entire CLI is missing from PATH.
func WrapProductionPlainTextWarningHookCommand(command string, format WarningFormat) string {
	return fmt.Sprintf(
		`sh -c 'if ! command -v entire >/dev/null 2>&1; then printf "%%s\n" %q; exit 0; fi; exec %s'`,
		MissingEntireWarning(format),
		command,
	)
}

const productionHookWrapperPrefix = `sh -c 'if ! command -v entire >/dev/null 2>&1; then `

// IsManagedHookCommand reports whether command is either a direct Entire hook
// command or one of Entire's production wrapper forms that exec that command.
func IsManagedHookCommand(command string, prefixes []string) bool {
	if hasManagedHookPrefix(command, prefixes) {
		return true
	}
	if !strings.HasPrefix(command, productionHookWrapperPrefix) {
		return false
	}

	_, wrappedCommand, ok := strings.Cut(command, "; fi; exec ")
	if !ok {
		return false
	}

	return hasManagedHookPrefix(wrappedCommand, prefixes)
}

func hasManagedHookPrefix(command string, prefixes []string) bool {
	for _, prefix := range prefixes {
		if strings.HasPrefix(command, prefix) {
			return true
		}
	}
	return false
}


--- cmd/entire/cli/agent/registry.go
package agent

import (
	"context"
	"fmt"
	"path/filepath"
	"runtime"
	"slices"
	"strings"
	"sync"

	"github.com/entireio/cli/cmd/entire/cli/agent/types"
)

var (
	registryMu sync.RWMutex
	registry   = make(map[types.AgentName]Factory)
)

// Factory creates a new agent instance
type Factory func() Agent

// Register adds an agent factory to the registry.
// Called from init() in each agent implementation.
func Register(name types.AgentName, factory Factory) {
	registryMu.Lock()
	defer registryMu.Unlock()
	registry[name] = factory
}

// Get retrieves an agent by name.
//

func Get(name types.AgentName) (Agent, error) {
	registryMu.RLock()
	defer registryMu.RUnlock()

	factory, ok := registry[name]
	if !ok {
		return nil, fmt.Errorf("unknown agent: %s (available: %v)", name, List())
	}
	return factory(), nil
}

// List returns all registered agent names in sorted order.
func List() []types.AgentName {
	registryMu.RLock()
	defer registryMu.RUnlock()

	names := make([]types.AgentName, 0, len(registry))
	for name := range registry {
		names = append(names, name)
	}
	slices.Sort(names)
	return names
}

// StringList returns user-facing agent names, excluding test-only agents.
func StringList() []string {
	registryMu.RLock()
	defer registryMu.RUnlock()

	names := make([]string, 0, len(registry))
	for name, factory := range registry {
		if to, ok := factory().(TestOnly); ok && to.IsTestOnly() {
			continue
		}
		names = append(names, string(name))
	}
	slices.Sort(names)
	return names
}

// DetectAll returns all agents whose DetectPresence reports true.
// Agents are checked in sorted name order (via List()) for deterministic results.
// Returns an empty slice when no agent is detected.
func DetectAll(ctx context.Context) []Agent {
	names := List() // sorted, lock-safe

	var detected []Agent
	for _, name := range names {
		ag, err := Get(name)
		if err != nil {
			continue
		}
		if present, err := ag.DetectPresence(ctx); err == nil && present {
			detected = append(detected, ag)
		}
	}
	return detected
}

// Detect attempts to auto-detect which agent is being used.
// Iterates registered agents in sorted name order for deterministic results.
// Returns the first agent whose DetectPresence reports true.
func Detect(ctx context.Context) (Agent, error) {
	detected := DetectAll(ctx)
	if len(detected) == 0 {
		return nil, fmt.Errorf("no agent detected (available: %v)", List())
	}
	return detected[0], nil
}

// AgentForTranscriptPath returns the registered agent whose session directory
// for repoPath contains the given transcript path. Used to disambiguate which
// agent owns a session when multiple agents' hooks fire for the same session
// ID — a Cursor transcript path uniquely identifies a Cursor session even
// when Claude Code's hook is the one firing.
//
// Returns (nil, false) if transcriptPath is empty, no agent claims it, or any
// registry lookup fails. Match is by directory prefix (with a separator) so
// "/x/.claude/projects/abc.jsonl" doesn't accidentally match an agent rooted
// at "/x/.claude/projects/ab".
//
//nolint:revive // AgentForTranscriptPath: stutter is intentional for package callers (agent.AgentForTranscriptPath reads naturally)
func AgentForTranscriptPath(transcriptPath, repoPath string) (Agent, bool) {
	if transcriptPath == "" {
		return nil, false
	}
	abs, err := filepath.Abs(transcriptPath)
	if err != nil {
		abs = transcriptPath
	}
	for _, name := range List() {
		ag, err := Get(name)
		if err != nil {
			continue
		}
		dir, err := ag.GetSessionDir(repoPath)
		if err != nil || dir == "" {
			continue
		}
		dirAbs, err := filepath.Abs(dir)
		if err != nil {
			dirAbs = dir
		}
		if pathHasDirPrefix(abs, dirAbs) {
			return ag, true
		}
	}
	return nil, false
}

// pathHasDirPrefix reports whether path is contained within dir (or equals it).
// Adds a trailing separator before prefix-matching so /a/bc doesn't match /a/b.
//
// On Windows, comparison is case-insensitive: NTFS/ReFS treat paths as
// case-insensitive, and filepath.Abs preserves whatever casing the input had,
// so a transcript path like `C:\Users\Bob\.cursor\...` and a session dir like
// `c:\users\bob\.cursor\...` refer to the same location but would not match
// under a byte-wise comparison.
func pathHasDirPrefix(path, dir string) bool {
	if runtime.GOOS == "windows" {
		path = strings.ToLower(path)
		dir = strings.ToLower(dir)
	}
	if path == dir {
		return true
	}
	if !strings.HasSuffix(dir, string(filepath.Separator)) {
		dir += string(filepath.Separator)
	}
	return strings.HasPrefix(path, dir)
}

// Agent name constants (registry keys)
const (
	AgentNameClaudeCode     types.AgentName = "claude-code"
	AgentNameCodex          types.AgentName = "codex"
	AgentNameCopilotCLI     types.AgentName = "copilot-cli"
	AgentNameCursor         types.AgentName = "cursor"
	AgentNameFactoryAIDroid types.AgentName = "factoryai-droid"
	AgentNameGemini         types.AgentName = "gemini"
	AgentNameOpenCode       types.AgentName = "opencode"
	AgentNamePi             types.AgentName = "pi"
)

// Agent type constants (type identifiers stored in metadata/trailers)
const (
	AgentTypeClaudeCode     types.AgentType = "Claude Code"
	AgentTypeCodex          types.AgentType = "Codex"
	AgentTypeCopilotCLI     types.AgentType = "Copilot CLI"
	AgentTypeCursor         types.AgentType = "Cursor"
	AgentTypeFactoryAIDroid types.AgentType = "Factory AI Droid"
	AgentTypeGemini         types.AgentType = "Gemini CLI"
	AgentTypeOpenCode       types.AgentType = "OpenCode"
	AgentTypePi             types.AgentType = "Pi"
	AgentTypeUnknown        types.AgentType = "Unknown"
)

// DefaultAgentName is the registry key for the default agent.
const DefaultAgentName types.AgentName = AgentNameClaudeCode

// GetByAgentType retrieves an agent by its type identifier.
//
// Note: This uses a linear search that instantiates agents until a match is found.
// This is acceptable because:
//   - Agent count is small (~2-20 agents)
//   - Agent factories are lightweight (empty struct allocation)
//   - Called infrequently (commit hooks, rewind, debug commands - not hot paths)
//   - Cost is ~400ns worst case vs milliseconds for I/O operations
//
// Only optimize if agent count exceeds 100 or profiling shows this as a bottleneck.
func GetByAgentType(agentType types.AgentType) (Agent, error) {
	registryMu.RLock()
	defer registryMu.RUnlock()

	for _, factory := range registry {
		ag := factory()
		if ag.Type() == agentType {
			return ag, nil
		}
	}

	return nil, fmt.Errorf("unknown agent type: %s", agentType)
}

// AllProtectedDirs returns the union of ProtectedDirs from all registered agents.
func AllProtectedDirs() []string {
	// Copy factories under the lock, then release before calling external code.
	registryMu.RLock()
	factories := make([]Factory, 0, len(registry))
	for _, f := range registry {
		factories = append(factories, f)
	}
	registryMu.RUnlock()

	seen := make(map[string]struct{})
	var dirs []string
	for _, factory := range factories {
		for _, d := range factory().ProtectedDirs() {
			if _, ok := seen[d]; !ok {
				seen[d] = struct{}{}
				dirs = append(dirs, d)
			}
		}
	}
	slices.Sort(dirs)
	return dirs
}

// AllProtectedFiles returns the union of ProtectedFiles from all registered agents.
func AllProtectedFiles() []string {
	// Copy factories under the lock, then release before calling external code.
	registryMu.RLock()
	factories := make([]Factory, 0, len(registry))
	for _, f := range registry {
		factories = append(factories, f)
	}
	registryMu.RUnlock()

	seen := make(map[string]struct{})
	var files []string
	for _, factory := range factories {
		pf, ok := factory().(ProtectedFilesProvider)
		if !ok {
			continue
		}
		for _, file := range pf.ProtectedFiles() {
			if _, ok := seen[file]; !ok {
				seen[file] = struct{}{}
				files = append(files, file)
			}
		}
	}
	slices.Sort(files)
	return files
}

// LauncherFor returns the Launcher implementation for the given agent name,
// or ok=false if the agent does not support subprocess launching. Callers
// should tell the user to start the agent manually in that case.
func LauncherFor(name types.AgentName) (Launcher, bool) {
	a, err := Get(name)
	if err != nil {
		return nil, false
	}
	l, ok := a.(Launcher)
	return l, ok
}

// Default returns the default agent.
// Returns nil if the default agent is not registered.
//
//nolint:errcheck // Factory pattern returns interface; error is acceptable to ignore for default
func Default() Agent {
	a, _ := Get(DefaultAgentName)
	return a
}


--- cmd/entire/cli/agent/session.go
package agent

import (
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent/types"
)

// AgentSession represents a coding session's data.
// Each agent stores data in its native format (JSONL, SQLite, Markdown, etc.)
// and only the originating agent can read/write it.
//
// Design: Sessions are NOT interoperable between agents. A session created by
// Claude Code can only be read/written by Claude Code. This simplifies the
// implementation as we don't need format conversion.
//
//nolint:revive // AgentSession is clearer than Session in context of the package
type AgentSession struct {
	SessionID  string
	AgentName  types.AgentName
	RepoPath   string
	SessionRef string // Path/reference to session in agent's storage
	StartTime  time.Time

	// NativeData holds the session content in the agent's native format.
	// Only the originating agent can interpret this data.
	// Examples:
	//   - Claude Code: raw JSONL bytes
	//   - Cursor: serialized SQLite rows
	//   - Aider: Markdown content
	NativeData []byte

	// Computed fields - populated by the agent when reading
	ModifiedFiles []string
	NewFiles      []string
	DeletedFiles  []string

	// Optional normalized entries - agents may populate this if needed
	// for operations that benefit from structured access
	Entries []SessionEntry
}

// SessionEntry represents a single entry in the session
type SessionEntry struct {
	UUID      string
	Type      EntryType
	Timestamp time.Time
	Content   string

	// Tool-specific fields
	ToolName      string
	ToolInput     interface{}
	ToolOutput    interface{}
	FilesAffected []string
}

// EntryType categorizes session entries
type EntryType string

const (
	EntryUser      EntryType = "user"
	EntryAssistant EntryType = "assistant"
	EntryTool      EntryType = "tool"
	EntrySystem    EntryType = "system"
)

// GetLastUserPrompt returns the last user message content
func (s *AgentSession) GetLastUserPrompt() string {
	for i := len(s.Entries) - 1; i >= 0; i-- {
		if s.Entries[i].Type == EntryUser {
			return s.Entries[i].Content
		}
	}
	return ""
}

// GetLastAssistantResponse returns the last assistant message content
func (s *AgentSession) GetLastAssistantResponse() string {
	for i := len(s.Entries) - 1; i >= 0; i-- {
		if s.Entries[i].Type == EntryAssistant {
			return s.Entries[i].Content
		}
	}
	return ""
}

// TruncateAtUUID returns a new session truncated at the given UUID (inclusive)
func (s *AgentSession) TruncateAtUUID(uuid string) *AgentSession {
	if uuid == "" {
		return s
	}

	truncated := &AgentSession{
		SessionID:  s.SessionID,
		AgentName:  s.AgentName,
		RepoPath:   s.RepoPath,
		SessionRef: s.SessionRef,
		StartTime:  s.StartTime,
	}

	for i, entry := range s.Entries {
		truncated.Entries = append(truncated.Entries, entry)
		if entry.UUID == uuid {
			truncated.Entries = s.Entries[:i+1]
			break
		}
	}

	// Recompute file lists from truncated entries
	fileSet := make(map[string]bool)
	for _, entry := range truncated.Entries {
		for _, f := range entry.FilesAffected {
			if !fileSet[f] {
				fileSet[f] = true
				truncated.ModifiedFiles = append(truncated.ModifiedFiles, f)
			}
		}
	}

	return truncated
}

// FindToolResultUUID finds the UUID of the entry containing the tool result
// for the given tool use ID. Returns the UUID and true if found.
func (s *AgentSession) FindToolResultUUID(toolUseID string) (string, bool) {
	for _, entry := range s.Entries {
		if entry.Type == EntryTool && entry.UUID == toolUseID {
			return entry.UUID, true
		}
	}
	return "", false
}


--- cmd/entire/cli/agent/text_generator_cli.go
package agent

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent/types"
)

// TextCommandRunner matches exec.CommandContext and allows tests to inject a runner.
type TextCommandRunner func(ctx context.Context, name string, args ...string) *exec.Cmd

// RunIsolatedTextGeneratorCLI executes a text-generation CLI in an isolated temp
// directory with all GIT_* environment variables removed. This avoids recursive
// hook triggers and repo side effects while preserving provider-specific flags.
func RunIsolatedTextGeneratorCLI(ctx context.Context, runner TextCommandRunner, binary, displayName string, args []string, stdin string) (string, error) {
	if runner == nil {
		runner = exec.CommandContext
	}

	cmd := runner(ctx, binary, args...)
	cmd.Dir = os.TempDir()
	cmd.Env = StripGitEnv(os.Environ())
	if stdin != "" {
		cmd.Stdin = strings.NewReader(stdin)
	}

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	if err := cmd.Run(); err != nil {
		if errors.Is(ctx.Err(), context.DeadlineExceeded) {
			return "", context.DeadlineExceeded
		}
		if errors.Is(ctx.Err(), context.Canceled) {
			return "", context.Canceled
		}
		var execErr *exec.Error
		if errors.As(err, &execErr) {
			return "", fmt.Errorf("%s CLI not found: %w", displayName, err)
		}
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			detail := strings.TrimSpace(stderr.String())
			if detail == "" {
				detail = strings.TrimSpace(stdout.String())
			}
			if detail == "" {
				detail = err.Error()
			}
			return "", fmt.Errorf("%s CLI failed (exit %d): %s: %w", displayName, exitErr.ExitCode(), detail, err)
		}
		return "", fmt.Errorf("failed to run %s CLI: %w", displayName, err)
	}

	result := strings.TrimSpace(stdout.String())
	if result == "" {
		return "", fmt.Errorf("%s CLI returned empty output", displayName)
	}
	return result, nil
}

// summaryProviderBinaries maps agent names to the CLI binary that
// RunIsolatedTextGeneratorCLI will exec. Used by IsSummaryCLIAvailable to
// check PATH instead of repo-level DetectPresence, because a repo can use
// one agent for development while a different agent generates summaries.
var summaryProviderBinaries = map[types.AgentName]string{
	AgentNameClaudeCode: "claude",
	AgentNameCodex:      "codex",
	AgentNameCopilotCLI: "copilot",
	AgentNameCursor:     "agent",
	AgentNameGemini:     "gemini",
}

// IsSummaryCLIAvailable reports whether the CLI binary for a summary-capable
// agent is on PATH. This is distinct from DetectPresence, which checks
// repo-level agent configuration — a repo configured with Claude Code for
// development can still use Codex or Gemini for summary generation as long
// as the binary is installed.
func IsSummaryCLIAvailable(name types.AgentName) bool {
	binary, ok := summaryProviderBinaries[name]
	if !ok {
		return false
	}
	_, err := exec.LookPath(binary)
	return err == nil
}

func StripGitEnv(env []string) []string {
	filtered := make([]string, 0, len(env))
	for _, e := range env {
		if !strings.HasPrefix(e, "GIT_") {
			filtered = append(filtered, e)
		}
	}
	return filtered
}


